SELECT 
FROM admin_user u JOIN admin_group g ON g.id = u.group_id
WHERE u.login_id = #{loginId}

SELECT 
FROM admin_user u JOIN admin_group g ON g.id = u.group_id
WHERE u.id = #{id}

SELECT program_id, array_to_string(actions, '|') AS actions
FROM group_permission
WHERE group_id = #{groupId}
